mapper.sql:
FROM physical_room r
WHERE r.tenant_id = #{w.tenantId}
  AND r.hotel_id = #{w.hotelId}
  AND r.status = 'ACTIVE'

  AND r.room_type_id = #{w.roomTypeId}

mapper.select:
SELECT d.stay_date, r.room_type_id, count(*)::int AS total_rooms, count(*) FILTER (WHERE )::int AS sold_rooms, count(*) FILTER (WHERE )::int AS blocked_rooms, (count(*) - count(*) FILTER (WHERE ) - count(*) FILTER (WHERE ))::int AS available_rooms FROM physical_room r CROSS JOIN d WHERE r.tenant_id = #{w.tenantId} AND r.hotel_id = #{w.hotelId} AND r.status = 'ACTIVE'
AND r.room_type_id = #{w.roomTypeId}
GROUP BY d.stay_date, r.room_type_id ORDER BY d.stay_date, r.room_type_id

SELECT room_id, stay_date, reservation_unavailable, block_unavailable, source_room_version
FROM room_inventory_day
WHERE tenant_id = #{w.tenantId}
  AND hotel_id = #{w.hotelId}
  AND stay_date >= #{w.from}::date
  AND stay_date < #{w.to}::date

mapper.delete:
DELETE FROM room_inventory_day
WHERE tenant_id = #{w.tenantId}
  AND hotel_id = #{w.hotelId}
  AND stay_date >= #{w.from}::date
  AND stay_date < #{w.to}::date
